`,(0,n.jsxs)(r.li,{children:[(0,n.jsx)(r.strong,{children:"Templates:"})," spreadsheet with formulas, presentation layouts, document styles"]}),`
`,(0,n.jsxs)(r.li,{children:[(0,n.jsx)(r.strong,{children:"Data files:"})," CSV lookup tables, JSON configurations, pricing databases"]}),`
